CREATE OR REPLACE FUNCTION public.pm_quote_internal_fee(_quote uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce(sum(CASE WHEN s.stage_kind='retainer_monthly' AND s.retainer_monthly_amount>0 THEN s.retainer_monthly_amount*greatest(1,coalesce(s.retainer_months,1)) WHEN coalesce(nullif(s.sale_source,''),q.fee_source_mode,'allocation')='budget' THEN coalesce(s.budget,0) ELSE coalesce((SELECT sum((SELECT count(*) FROM generate_series(a.start_date::timestamp,a.end_date::timestamp,interval '1 day') d WHERE extract(isodow FROM d)<6)*a.hours_per_day*a.sale_rate_snapshot) FROM quote_allocations a WHERE a.stage_id=s.id),0)*CASE WHEN s.stage_kind='retainer_monthly' THEN greatest(1,coalesce(s.retainer_months,1)) ELSE 1 END END),0)*coalesce(nullif(q.pricing_multiplier,0),1) FROM fee_proposals q LEFT JOIN quote_stages s ON s.quote_id=q.id AND coalesce(s.stage_role,'')<>'client' AND NOT EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=s.id) WHERE q.id=_quote GROUP BY q.pricing_multiplier $$;
DO $migration$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.pm_convert_relative_quote(uuid,date,text)'::regprocedure) INTO definition; definition:=replace(definition,'e.sale_price,e.sale_price_manual,e.status::text::pm_external_service_status','pm_quote_external_line_fee(e.id)/greatest(e.quantity,0.000001),true,e.status::text::pm_external_service_status'); EXECUTE definition; END $migration$;